// DeepCopyInto copies all properties into another ProxyCache.
func (in *ProxyCache) DeepCopyInto(out *ProxyCache) {
	*out = *in
	out.TypeMeta = in.TypeMeta
	in.ObjectMeta.DeepCopyInto(&out.ObjectMeta)
	in.Spec.DeepCopyInto(&out.Spec)
	in.Status.DeepCopyInto(&out.Status)
}

// DeepCopy returns a deep copy of ProxyCache.
func (in *ProxyCache) DeepCopy() *ProxyCache {
	if in == nil {
		return nil
	}
	out := new(ProxyCache)
	in.DeepCopyInto(out)
	return out
}

// DeepCopyObject returns a deep copy as runtime.Object.
func (in *ProxyCache) DeepCopyObject() runtime.Object {
	if c := in.DeepCopy(); c != nil {
		return c
	}
	return nil
}

// DeepCopyInto copies all properties into another ProxyCacheList.
func (in *ProxyCacheList) DeepCopyInto(out *ProxyCacheList) {
	*out = *in
